import java.io.*;
import java.util.*;
import java.text.*;

public class Main {
    public static void main(String[] args) throws Exception {
        String filePath = "<tmp>";

        List<String> lines = new ArrayList<>();
        BufferedReader br = new BufferedReader(new FileReader(filePath));
        String line;
        while ((line = br.readLine()) != null) {
            lines.add(line);
        }
        br.close();

        Map<String, List<Double>> deptSalaries = new TreeMap<>();
        Map<String, Integer> deptCount = new TreeMap<>();
        String highestName = "";
        double highestSalary = -1;
        double totalBudget = 0;

        for (int i = 1; i < lines.size(); i++) {
            String[] parts = lines.get(i).split(",");
            if (parts.length < 6) continue;

            String name = parts[1].trim();
            String department = parts[2].trim();
            double salary = Double.parseDouble(parts[3].trim());

            deptSalaries.computeIfAbsent(department, k -> new ArrayList<>()).add(salary);
            deptCount.merge(department, 1, Integer::sum);
            totalBudget += salary;

            if (salary > highestSalary) {
                highestSalary = salary;
                highestName = name;
            }
        }

        DecimalFormat avgFmt = new DecimalFormat("#,##0.00", new DecimalFormatSymbols(Locale.US));
        DecimalFormat intFmt = new DecimalFormat("#,##0", new DecimalFormatSymbols(Locale.US));

        StringBuilder sb = new StringBuilder();
        sb.append("=== Salary Report ===\n");
        sb.append("\n");
        sb.append("Average Salary by Department:\n");

        for (Map.Entry<String, List<Double>> entry : deptSalaries.entrySet()) {
            double avg = entry.getValue().stream().mapToDouble(Double::doubleValue).average().orElse(0);
            sb.append(String.format("  %s: $%s\n", entry.getKey(), avgFmt.format(avg)));
        }

        sb.append("\n");
        sb.append(String.format("Highest Paid: %s ($%s)\n", highestName, intFmt.format((long) highestSalary)));

        sb.append("\n");
        sb.append("Departments with >2 employees:\n");
        for (Map.Entry<String, Integer> entry : deptCount.entrySet()) {
            if (entry.getValue() > 2) {
                sb.append(String.format("  %s (%d employees)\n", entry.getKey(), entry.getValue()));
            }
        }

        sb.append("\n");
        sb.append(String.format("Total Budget: $%s\n", intFmt.format((long) totalBudget)));

        System.out.print(sb.toString());
    }
}

