let filePath = "<tmp>"

guard let content = try? String(contentsOfFile: filePath, encoding: .utf8) else {
    FileHandle.standardError.write("Cannot read file\n".data(using: .utf8)!)
    exit(1)
}

var lines = content.components(separatedBy: "\n").map { $0.replacingOccurrences(of: "\r", with: "") }
lines = lines.filter { !$0.trimmingCharacters(in: .whitespaces).isEmpty }

let dataLines = Array(lines.dropFirst())

struct Employee {
    let name: String
    let department: String
    let salary: Double
}

var employees: [Employee] = []
for line in dataLines {
    let cols = line.components(separatedBy: ",")
    if cols.count >= 6 {
        let name = cols[1].trimmingCharacters(in: .whitespaces)
        let department = cols[2].trimmingCharacters(in: .whitespaces)
        let salaryStr = cols[3].trimmingCharacters(in: .whitespaces)
        let salary = Double(salaryStr) ?? 0
        employees.append(Employee(name: name, department: department, salary: salary))
    }
}

func formatInt(_ value: Int) -> String {
    let formatter = NumberFormatter()
    formatter.numberStyle = .decimal
    formatter.groupingSeparator = ","
    formatter.groupingSize = 3
    formatter.usesGroupingSeparator = true
    formatter.maximumFractionDigits = 0
    formatter.minimumFractionDigits = 0
    return formatter.string(from: NSNumber(value: value)) ?? "\(value)"
}

func formatDouble(_ value: Double) -> String {
    let formatter = NumberFormatter()
    formatter.numberStyle = .decimal
    formatter.groupingSeparator = ","
    formatter.groupingSize = 3
    formatter.usesGroupingSeparator = true
    formatter.minimumFractionDigits = 2
    formatter.maximumFractionDigits = 2
    return formatter.string(from: NSNumber(value: value)) ?? String(format: "%.2f", value)
}

var deptSalaries: [String: [Double]] = [:]
for emp in employees {
    deptSalaries[emp.department, default: []].append(emp.salary)
}

var avgByDept: [String: Double] = [:]
for (dept, salaries) in deptSalaries {
    avgByDept[dept] = salaries.reduce(0, +) / Double(salaries.count)
}

let highestPaid = employees.max(by: { $0.salary < $1.salary })

var deptCounts: [String: Int] = [:]
