import * as fs from 'fs';

const logPath = '<tmp>';
const content: string = fs.readFileSync(logPath, 'utf-8');
const lines: string[] = content.split('\n').filter((line: string) => line.trim() !== '');

const levelRegex = /\[(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})\] (\w+) \(([^)]+)\) - (.+)/;

const levelCounts: Map<string, number> = new Map();
const errorComponentCounts: Map<string, number> = new Map();
const errorMessages: Set<string> = new Set();
const hourCounts: Map<string, number> = new Map();

for (const line of lines) {
  const match = line.match(levelRegex);
  if (!match) continue;

  const timestamp: string = match[1];
  const level: string = match[2];
  const component: string = match[3];
  const message: string = match[4];

  levelCounts.set(level, (levelCounts.get(level) || 0) + 1);

  if (level === 'ERROR') {
    errorComponentCounts.set(component, (errorComponentCounts.get(component) || 0) + 1);
    errorMessages.add(message);
  }

  const hour: string = timestamp.substring(11, 13);
  hourCounts.set(hour, (hourCounts.get(hour) || 0) + 1);
}

let output: string = '=== Log Analysis ===\n';
output += '\n';
output += 'Entries by Level:\n';
const sortedLevels: [string, number][] = [...levelCounts.entries()].sort((a, b) => a[0].localeCompare(b[0]));
for (const [level, count] of sortedLevels) {
  output += `  ${level}: ${count}\n`;
}
output += '\n';

let maxErrComponent: string = '';
let maxErrCount: number = 0;
for (const [comp, count] of errorComponentCounts) {
  if (count > maxErrCount) {
    maxErrCount = count;
    maxErrComponent = comp;
  }
}
output += `Component with Most Errors: ${maxErrComponent} (${maxErrCount} errors)\n`;
output += '\n';

output += 'Unique Error Messages:\n';
const sortedMessages: string[] = [...errorMessages].sort((a, b) => a.localeCompare(b));
for (const msg of sortedMessages) {
  output += `  - ${msg}\n`;
}
output += '\n';

let maxHour: string = '';
let maxHourCount: number = 0;
for (const [hour, count] of hourCounts) {
  if (count > maxHourCount) {
    maxHourCount = count;
    maxHour = hour;
  }
}
output += `Busiest Hour: ${maxHour}:00 (${maxHourCount} entries)\n`;

process.stdout.write(output);

