declare function require(name: string): any;

const fs = require('fs');

const csvPath = '<tmp>';
const csvContent: string = fs.readFileSync(csvPath, 'utf-8');

const lines: string[] = csvContent.trim().split('\n');

interface Employee {
  employee_id: string;
  name: string;
  department: string;
  salary: number;
  start_date: string;
  rating: string;
}

const employees: Employee[] = [];

for (let i = 1; i < lines.length; i++) {
  const cols: string[] = lines[i].split(',');
  employees.push({
    employee_id: cols[0].trim(),
    name: cols[1].trim(),
    department: cols[2].trim(),
    salary: parseFloat(cols[3].trim()),
    start_date: cols[4].trim(),
    rating: cols[5].trim(),
  });
}

function addCommas(n: number): string {
  return n.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
}

function formatMoney2(n: number): string {
  const s = n.toFixed(2);
  const parts = s.split('.');
  const intPart = parts[0].replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return intPart + '.' + parts[1];
}

function formatMoneyInt(n: number): string {
  return addCommas(Math.round(n));
}

const deptSalaries: Map<string, number[]> = new Map();
for (const emp of employees) {
  if (!deptSalaries.has(emp.department)) {
    deptSalaries.set(emp.department, []);
  }
  deptSalaries.get(emp.department)!.push(emp.salary);
}

const sortedDepts: string[] = Array.from(deptSalaries.keys()).sort();

let out = '';
out += '=== Salary Report ===\n';
out += '\n';
out += 'Average Salary by Department:\n';
for (const dept of sortedDepts) {
  const salaries = deptSalaries.get(dept)!;
  const avg = salaries.reduce((a, b) => a + b, 0) / salaries.length;
  out += '  ' + dept + ': $' + formatMoney2(avg) + '\n';
}

