use std::fs;
use std::collections::HashMap;

fn format_commas(n: f64, decimals: usize) -> String {
    let negative = n < 0.0;
    let n = n.abs();
    let formatted = format!("{:.*}", decimals, n);
    let (int_part, dec_part) = if decimals > 0 {
        let pos = formatted.find('.').unwrap();
        (&formatted[..pos], &formatted[pos..])
    } else {
        (formatted.as_str(), "")
    };

    let int_chars: Vec<char> = int_part.chars().collect();
    let mut result = String::new();
    for (i, c) in int_chars.iter().enumerate() {
        if i > 0 && (int_chars.len() - i) % 3 == 0 {
            result.push(',');
        }
        result.push(*c);
    }
    if decimals > 0 {
        result.push_str(dec_part);
    }
    if negative {
        result.insert(0, '-');
    }
    result
}

fn main() {
    let path = "<tmp>";
    let content = fs::read_to_string(path).expect("Failed to read CSV file");

    let mut lines = content.lines();
    let _header = lines.next().unwrap();

    let mut dept_salaries: HashMap<String, Vec<f64>> = HashMap::new();
    let mut highest_paid: (String, f64) = (String::new(), f64::MIN);
    let mut total_budget: f64 = 0.0;
    let mut dept_counts: HashMap<String, usize> = HashMap::new();

    for line in lines {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        let fields: Vec<&str> = line.split(',').collect();
        if fields.len() < 6 {
            continue;
        }

        let name = fields[1].trim();
        let department = fields[2].trim();
        let salary: f64 = fields[3].trim().parse().unwrap_or(0.0);

        dept_salaries.entry(department.to_string()).or_insert_with(Vec::new).push(salary);
        *dept_counts.entry(department.to_string()).or_insert(0) += 1;

        if salary > highest_paid.1 {
            highest_paid = (name.to_string(), salary);
        }

        total_budget += salary;
    }

    let mut depts: Vec<&String> = dept_salaries.keys().collect();
    depts.sort();

    print!("=== Salary Report ===\n");
    print!("\n");
    print!("Average Salary by Department:\n");
    for dept in &depts {
        let salaries = &dept_salaries[*dept];
        let avg: f64 = salaries.iter().sum::<f64>() / salaries.len() as f64;
        print!("  {}: ${}\n", dept, format_commas(avg, 2));
    }
    print!("\n");
    print!("Highest Paid: {} (${})\n", highest_paid.0, format_commas(highest_paid.1, 0));
    print!("\n");

    let mut multi_depts: Vec<&String> = dept_counts.iter()
        .filter(|(_, &count)| count > 2)
        .map(|(d, _)| d)
        .collect();
    multi_depts.sort();

    print!("Departments with >2 employees:\n");
    for dept in &multi_depts {
        let count = dept_counts[*dept];
        print!("  {} ({} employees)\n", dept, count);
    }
    print!("\n");
    print!("Total Budget: ${}\n", format_commas(total_budget, 0));
}

