        let hour_key = format!("{}:00", hour);
        *hour_counts.entry(hour_key).or_insert(0) += 1;

        let rest_trimmed = rest.trim_start();

        let level_end = rest_trimmed.find(' ').unwrap_or(rest_trimmed.len());
        let level = &rest_trimmed[..level_end];
        *level_counts.entry(level.to_string()).or_insert(0) += 1;

        let after_level = rest_trimmed[level_end..].trim_start();

        let paren_open = match after_level.find('(') {
            Some(pos) => pos,
            None => continue,
        };
        let paren_close = match after_level[paren_open..].find(')') {
            Some(pos) => paren_open + pos,
            None => continue,
        };

        let component = &after_level[paren_open + 1..paren_close];

        let after_component = &after_level[paren_close + 1..];

        let dash_pos = match after_component.find(" - ") {
            Some(pos) => pos,
            None => continue,
        };

        let message = &after_component[dash_pos + 3..];

        if level == "ERROR" {
            *error_component_counts.entry(component.to_string()).or_insert(0) += 1;
            error_messages.insert(message.to_string());
        }
    }

    println!("=== Log Analysis ===");
    println!();
    println!("Entries by Level:");
    for (level, count) in &level_counts {
        println!("  {}: {}", level, count);
    }
    println!();

    let (top_component, top_count) = error_component_counts.iter()
        .max_by_key(|(_, count)| *count)
        .map(|(c, n)| (c.as_str(), *n))
        .unwrap_or(("", 0));
    println!("Component with Most Errors: {} ({} errors)", top_component, top_count);
    println!();

    println!("Unique Error Messages:");
    for msg in &error_messages {
        println!("  - {}", msg);
    }
    println!();

    let (top_hour, top_hour_count) = hour_counts.iter()
        .max_by_key(|(_, count)| *count)
        .map(|(h, n)| (h.as_str(), *n))
        .unwrap_or(("00:00", 0));
    println!("Busiest Hour: {} ({} entries)", top_hour, top_hour_count);
