public class Main {

    static int pos;
    static String json;

    static void skipWhitespace() {
        while (pos < json.length() && Character.isWhitespace(json.charAt(pos))) pos++;
    }

    static char peek() {
        return pos < json.length() ? json.charAt(pos) : '\0';
    }

    static char next() {
        return json.charAt(pos++);
    }

    static Object parseValue() {
        skipWhitespace();
        char c = peek();
        if (c == '[') return parseArray();
        if (c == '{') return parseObject();
        if (c == '"') return parseString();
        if (c == '-' || Character.isDigit(c)) return parseNumber();
        if (c == 't') { pos += 4; return Boolean.TRUE; }
        if (c == 'f') { pos += 5; return Boolean.FALSE; }
        if (c == 'n') { pos += 4; return null; }
        throw new RuntimeException("Unexpected char: " + c + " at pos " + pos);
    }

    static List<Object> parseArray() {
        next(); // [
        List<Object> list = new ArrayList<>();
        skipWhitespace();
        if (peek() == ']') { next(); return list; }
        while (true) {
            list.add(parseValue());
            skipWhitespace();
            char c = next();
            if (c == ']') break;
            // c should be ','
        }
        return list;
    }

    static Map<String, Object> parseObject() {
        next(); // {
        Map<String, Object> map = new LinkedHashMap<>();
        skipWhitespace();
        if (peek() == '}') { next(); return map; }
        while (true) {
            skipWhitespace();
            String key = parseString();
            skipWhitespace();
            next(); // :
            Object val = parseValue();
            map.put(key, val);
            skipWhitespace();
            char c = next();
            if (c == '}') break;
            // c should be ','
        }
        return map;
    }

    static String parseString() {
        next(); // opening "
        StringBuilder sb = new StringBuilder();
        while (true) {
            char c = next();
            if (c == '"') break;
            if (c == '\\') {
                char e = next();
                switch (e) {
                    case '"': sb.append('"'); break;
                    case '\\': sb.append('\\'); break;
                    case '/': sb.append('/'); break;
                    case 'b': sb.append('\b'); break;
                    case 'f': sb.append('\f'); break;
                    case 'n': sb.append('\n'); break;
                    case 'r': sb.append('\r'); break;
                    case 't': sb.append('\t'); break;
                    case 'u':
                        String hex = json.substring(pos, pos + 4);
                        pos += 4;
                        sb.append((char) Integer.parseInt(hex, 16));
                        break;
                    default: throw new RuntimeException("Bad escape: " + e);
                }
            } else {
                sb.append(c);
            }
        }
        return sb.toString();
    }

    static Number parseNumber() {
        int start = pos;
        if (peek() == '-') next();
        while (pos < json.length() && Character.isDigit(json.charAt(pos))) pos++;
        boolean isDouble = false;
        if (pos < json.length() && json.charAt(pos) == '.') {
