            }
        }

        filtered.sort((a, b) -> {
            String nameA = (String) a.get("name");
            String nameB = (String) b.get("name");
            return nameA.compareTo(nameB);
        });

        System.out.println("=== Filtered Products (price > $50.00) ===");
        System.out.println();

        double total = 0.0;
        for (Map<String, Object> map : filtered) {
            String name = (String) map.get("name");
            double price = ((Number) map.get("price")).doubleValue();
            total += price;
            System.out.printf("%s: $%.2f%n", name, price);
        }

        System.out.println();
        System.out.printf("Count: %d%n", filtered.size());
        System.out.printf("Total: $%.2f%n", total);
    }
}

