import * as fs from 'fs';

interface Edge {
    from: string;
    to: string;
    weight: number;
}

interface GraphData {
    nodes: string[];
    edges: Edge[];
}

function main(): void {
    const filePath = '<tmp>';
    const raw = fs.readFileSync(filePath, 'utf-8');
    const data: GraphData = JSON.parse(raw);

    const nodes: string[] = data.nodes;
    const edges: Edge[] = data.edges;

    // Build adjacency list (undirected)
    const adj: Map<string, { to: string; weight: number }[]> = new Map();
    for (const node of nodes) {
        adj.set(node, []);
    }
    for (const e of edges) {
        if (!adj.has(e.from)) adj.set(e.from, []);
        if (!adj.has(e.to)) adj.set(e.to, []);
        adj.get(e.from)!.push({ to: e.to, weight: e.weight });
        adj.get(e.to)!.push({ to: e.from, weight: e.weight });
    }

    // Dijkstra's algorithm from node "A"
    const dist: Map<string, number> = new Map();
    for (const node of nodes) {
        dist.set(node, Infinity);
    }
    dist.set('A', 0);

    const visited: Set<string> = new Set();
    const unvisited: Set<string> = new Set(nodes);

    while (unvisited.size > 0) {
        // Select unvisited node with minimum distance
        let minNode: string | null = null;
        let minDist: number = Infinity;
        for (const node of unvisited) {
            const d = dist.get(node)!;
            if (d < minDist) {
                minDist = d;
                minNode = node;
            }
        }

        if (minNode === null || minDist === Infinity) {
            break;
        }

        unvisited.delete(minNode);
        visited.add(minNode);

        // Relax all edges from minNode
        const neighbors = adj.get(minNode)!;
        for (const { to, weight } of neighbors) {
            if (visited.has(to)) continue;
            const newDist = dist.get(minNode)! + weight;
            if (newDist < dist.get(to)!) {
                dist.set(to, newDist);
            }
        }
    }

    // Output
    const sorted = [...nodes].sort();
    const lines: string[] = [];
    lines.push('=== Shortest Paths from A ===');
    lines.push('');
    for (const node of sorted) {
        const d = dist.get(node)!;
        const distStr = d === Infinity ? 'unreachable' : String(d);
        lines.push(`A -> ${node}: ${distStr}`);
    }

    process.stdout.write(lines.join('\n') + '\n');
}

main();

