    const total = filtered.reduce((sum, p) => sum + p.price, 0);
    out += `Total: $${total.toFixed(2)}\n`;
    process.stdout.write(out);
  });
}).on("error", (err: Error) => {
  process.stderr.write(err.message + "\n");
  process.exit(1);
});

