import java.io.InputStreamReader;

public class Main {
    public static void main(String[] args) throws Exception {
        String os = runCommand("uname -s");
        String architecture = runCommand("uname -m");
        String username = runCommand("whoami");
        String hostname = runCommand("hostname");

        String json = "{\n"
            + "  \"hostname\": \"" + jsonEscape(hostname) + "\",\n"
            + "  \"os\": \"" + jsonEscape(os) + "\",\n"
            + "  \"architecture\": \"" + jsonEscape(architecture) + "\",\n"
            + "  \"username\": \"" + jsonEscape(username) + "\"\n"
            + "}";

        System.out.println(json);
    }

    private static String runCommand(String command) throws Exception {
        Process process = Runtime.getRuntime().exec(command);
        BufferedReader reader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = reader.readLine()) != null) {
            if (sb.length() > 0) sb.append("\n");
            sb.append(line);
        }
        reader.close();
        process.waitFor();
        return sb.toString().trim();
    }

    private static String jsonEscape(String s) {
        StringBuilder sb = new StringBuilder();
        for (char c : s.toCharArray()) {
            switch (c) {
                case '"': sb.append("\\\""); break;
                case '\\': sb.append("\\\\"); break;
                case '\n': sb.append("\\n"); break;
                case '\r': sb.append("\\r"); break;
                case '\t': sb.append("\\t"); break;
                default: sb.append(c);
            }
        }
        return sb.toString();
    }
}

