        s[len - 1] = '\0';
        len--;
    }
}

static char *run_command(const char *cmd) {
    FILE *fp = popen(cmd, "r");
    if (!fp) {
        char *empty = malloc(1);
        if (empty) empty[0] = '\0';
        return empty;
    }

    size_t cap = 4096;
    char *buf = malloc(cap);
    if (!buf) {
        pclose(fp);
        char *empty = malloc(1);
        if (empty) empty[0] = '\0';
        return empty;
    }

    size_t total = 0;
    size_t n;
    while ((n = fread(buf + total, 1, cap - total - 1, fp)) > 0) {
        total += n;
        if (total >= cap - 1) {
            cap *= 2;
