import java.nio.file.*;
import java.nio.file.attribute.BasicFileAttributes;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        Path root = Paths.get("<tmp>");

        List<Path> files = new ArrayList<>();

        Files.walkFileTree(root, new SimpleFileVisitor<Path>() {
            @Override
            public FileVisitResult preVisitDirectory(Path dir, BasicFileAttributes attrs) {
                if (Files.isSymbolicLink(dir)) {
                    return FileVisitResult.SKIP_SUBTREE;
                }
                return FileVisitResult.CONTINUE;
            }

            @Override
            public FileVisitResult visitFile(Path file, BasicFileAttributes attrs) {
                if (Files.isSymbolicLink(file)) {
                    return FileVisitResult.CONTINUE;
                }
                if (attrs.isRegularFile()) {
                    files.add(file);
                }
                return FileVisitResult.CONTINUE;
            }
        });

        files.sort((a, b) -> {
            String ra = root.relativize(a).toString().replace('\\', '/');
            String rb = root.relativize(b).toString().replace('\\', '/');
            return ra.compareTo(rb);
        });

        Map<String, List<String[]>> extMap = new TreeMap<>();
        long totalFiles = 0;
        long totalLines = 0;
        long totalChars = 0;

        for (Path file : files) {
            String relPath = root.relativize(file).toString().replace('\\', '/');
            String fileName = file.getFileName().toString();

            String ext = "";
            int dotIdx = fileName.lastIndexOf('.');
            if (dotIdx > 0 && dotIdx < fileName.length() - 1) {
                ext = fileName.substring(dotIdx);
            }

            long lines = 0;
            long chars = 0;
            boolean lastWasNewline = false;
            boolean hasContent = false;

            try (InputStream is = Files.newInputStream(file)) {
                int b;
                while ((b = is.read()) != -1) {
                    chars++;
                    hasContent = true;
                    if (b == '\n') {
                        lines++;
                        lastWasNewline = true;
                    } else {
                        lastWasNewline = false;
                    }
                }
            }

            if (hasContent && !lastWasNewline) {
                lines++;
            }

            totalFiles++;
            totalLines += lines;
            totalChars += chars;

            extMap.computeIfAbsent(ext, k -> new ArrayList<>()).add(new String[]{relPath, String.valueOf(lines), String.valueOf(chars)});
        }

        StringBuilder sb = new StringBuilder();
        sb.append("=== File Tree Analysis ===\n");
        sb.append("\n");

        for (Map.Entry<String, List<String[]>> entry : extMap.entrySet()) {
            String ext = entry.getKey();
            List<String[]> fileList = entry.getValue();

            long fCount = fileList.size();
            long fLines = 0;
            long fChars = 0;
            for (String[] f : fileList) {
                fLines += Long.parseLong(f[1]);
                fChars += Long.parseLong(f[2]);
            }

            sb.append("Extension: ").append(ext).append("\n");
            sb.append("  Files: ").append(fCount).append("\n");
            sb.append("  Total Lines: ").append(fLines).append("\n");
            sb.append("  Total Characters: ").append(fChars).append("\n");
            for (String[] f : fileList) {
                sb.append("    ").append(f[0]).append(": ").append(f[1]).append(" lines, ").append(f[2]).append(" chars\n");
            }
        }

        sb.append("\n");
        sb.append("Total: ").append(totalFiles).append(" files, ").append(totalLines).append(" lines, ").append(totalChars).append(" characters\n");

        System.out.print(sb.toString());
    }
}

