use std::collections::BTreeMap;
use std::fs;

#[derive(Debug, Clone, PartialEq)]
enum Json {
    Null,
    Bool(bool),
    Number(f64),
    String(String),
    Array(Vec<Json>),
    Object(BTreeMap<String, Json>),
}

struct Parser {
    chars: Vec<char>,
    pos: usize,
}

impl Parser {
    fn new(s: &str) -> Self {
        Parser { chars: s.chars().collect(), pos: 0 }
    }

    fn peek(&self) -> Option<char> {
        self.chars.get(self.pos).copied()
    }

    fn advance(&mut self) -> Option<char> {
        let c = self.peek();
        if c.is_some() {
            self.pos += 1;
        }
        c
    }

    fn skip_whitespace(&mut self) {
        while let Some(c) = self.peek() {
            if c == ' ' || c == '\t' || c == '\n' || c == '\r' {
                self.pos += 1;
            } else {
                break;
            }
        }
    }

    fn parse(&mut self) -> Json {
        self.skip_whitespace();
        self.parse_value()
    }

    fn parse_value(&mut self) -> Json {
        self.skip_whitespace();
        match self.peek() {
            Some('{') => self.parse_object(),
            Some('[') => self.parse_array(),
            Some('"') => Json::String(self.parse_string()),
            Some('t') => {
                self.expect_word("true");
                Json::Bool(true)
            }
            Some('f') => {
                self.expect_word("false");
                Json::Bool(false)
            }
            Some('n') => {
                self.expect_word("null");
                Json::Null
            }
            _ => self.parse_number(),
        }
    }

    fn expect_word(&mut self, word: &str) {
        for c in word.chars() {
            assert_eq!(self.advance(), Some(c), "Parse error");
        }
    }

    fn parse_object(&mut self) -> Json {
        self.advance();
        let mut map = BTreeMap::new();
        self.skip_whitespace();
        if self.peek() == Some('}') {
            self.advance();
            return Json::Object(map);
        }
        loop {
            self.skip_whitespace();
            let key = self.parse_string();
            self.skip_whitespace();
            assert_eq!(self.advance(), Some(':'), "Expected ':' in object");
            let value = self.parse_value();
            map.insert(key, value);
            self.skip_whitespace();
            match self.advance() {
                Some(',') => continue,
                Some('}') => break,
                _ => panic!("Expected ',' or '}' in object"),
            }
        }
        Json::Object(map)
    }

    fn parse_array(&mut self) -> Json {
        self.advance();
        let mut arr = Vec::new();
        self.skip_whitespace();
        if self.peek() == Some(']') {
            self.advance();
            return Json::Array(arr);
        }
        loop {
            let value = self.parse_value();
            arr.push(value);
            self.skip_whitespace();
            match self.advance() {
                Some(',') => continue,
                Some(']') => break,
                _ => panic!("Expected ',' or ']' in array"),
            }
        }
        Json::Array(arr)
    }

    fn parse_string(&mut self) -> String {
        assert_eq!(self.advance(), Some('"'), "Expected '\"'");
        let mut s = String::new();
        loop {
            match self.advance() {
                Some('"') => break,
                Some('\\') => match self.advance() {
                    Some('"') => s.push('"'),
                    Some('\\') => s.push('\\'),
                    Some('/') => s.push('/'),
                    Some('b') => s.push('\u{0008}'),
                    Some('f') => s.push('\u{000C}'),
                    Some('n') => s.push('\n'),
                    Some('r') => s.push('\r'),
                    Some('t') => s.push('\t'),
                    Some('u') => {
                        let mut code: u32 = 0;
                        for _ in 0..4 {
                            let c = self.advance().unwrap();
                            let d = match c {
                                '0'..='9' => (c as u32) - ('0' as u32),
                                'a'..='f' => (c as u32) - ('a' as u32) + 10,
                                'A'..='F' => (c as u32) - ('A' as u32) + 10,
                                _ => panic!("Invalid hex digit in \\u escape"),
                            };
                            code = code * 16 + d;
                        }
                        s.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                    }
                    _ => panic!("Invalid escape sequence"),
                },
                Some(c) => s.push(c),
                None => panic!("Unterminated string"),
            }
        }
        s
    }

    fn parse_number(&mut self) -> Json {
        let mut s = String::new();
        if self.peek() == Some('-') {
            s.push('-');
            self.advance();
        }
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() {
                s.push(c);
                self.advance();
            } else {
                break;
            }
        }
        if self.peek() == Some('.') {
            s.push('.');
            self.advance();
            while let Some(c) = self.peek() {
                if c.is_ascii_digit() {
                    s.push(c);
                    self.advance();
                } else {
                    break;
                }
            }
        }
        if matches!(self.peek(), Some('e') | Some('E')) {
            s.push(self.advance().unwrap());
            if matches!(self.peek(), Some('+') | Some('-')) {
                s.push(self.advance().unwrap());
            }
            while let Some(c) = self.peek() {
                if c.is_ascii_digit() {
                    s.push(c);
                    self.advance();
                } else {
                    break;
                }
            }
        }
        Json::Number(s.parse::<f64>().unwrap())
    }
}

fn escape_string(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        match c {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            '\u{0008}' => result.push_str("\\b"),
            '\u{000C}' => result.push_str("\\f"),
            c if (c as u32) < 0x20 => {
                result.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => result.push(c),
        }
    }
    result
}

fn serialize(value: &Json, indent: usize) -> String {
    let pad = "  ".repeat(indent);
    let inner = "  ".repeat(indent + 1);

    match value {
        Json::Null => "null".to_string(),
        Json::Bool(b) => b.to_string(),
        Json::Number(n) => format!("{}", n),
        Json::String(s) => format!("\"{}\"", escape_string(s)),
        Json::Array(arr) => {
            if arr.is_empty() {
                return "[]".to_string();
            }
            let items: Vec<String> = arr
                .iter()
                .map(|item| format!("{}{}", inner, serialize(item, indent + 1)))
                .collect();
            format!("[\n{}\n{}]", items.join(",\n"), pad)
        }
        Json::Object(map) => {
            if map.is_empty() {
                return "{}".to_string();
            }
            let items: Vec<String> = map
                .iter()
                .map(|(k, v)| {
                    format!(
                        "{}\"{}\": {}",
                        inner,
                        escape_string(k),
                        serialize(v, indent + 1)
                    )
                })
                .collect();
            format!("{{\n{}\n{}}}", items.join(",\n"), pad)
        }
    }
}

fn deep_merge(a: Json, b: Json) -> Json {
    match (a, b) {
        (Json::Object(mut obj_a), Json::Object(obj_b)) => {
            for (key, val_b) in obj_b {
                match obj_a.get_mut(&key) {
                    Some(existing) => {
                        let old = std::mem::replace(existing, Json::Null);
                        *existing = deep_merge(old, val_b);
                    }
                    None => {
                        obj_a.insert(key, val_b);
                    }
                }
            }
            Json::Object(obj_a)
        }
        (Json::Array(mut arr_a), Json::Array(arr_b)) => {
            for item in arr_b {
                if !arr_a.contains(&item) {
                    arr_a.push(item);
                }
            }
            Json::Array(arr_a)
        }
        (_, b) => b,
    }
}

fn main() {
    let path_a =
        "<tmp>";
    let path_b =
        "<tmp>";

    let content_a = fs::read_to_string(path_a).expect("Failed to read config_a.json");
    let content_b = fs::read_to_string(path_b).expect("Failed to read config_b.json");

    let json_a = Parser::new(&content_a).parse();
    let json_b = Parser::new(&content_b).parse();

    let merged = deep_merge(json_a, json_b);

    println!("{}", serialize(&merged, 0));
}

