                        s.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                    }
                    _ => panic!("Invalid escape sequence"),
                },
                Some(c) => s.push(c),
                None => panic!("Unterminated string"),
            }
        }
        s
    }

    fn parse_number(&mut self) -> Json {
        let mut s = String::new();
        if self.peek() == Some('-') {
            s.push('-');
            self.advance();
        }
        while let Some(c) = self.peek() {
            if c.is_ascii_digit() {
                s.push(c);
                self.advance();
            } else {
                break;
            }
        }
        if self.peek() == Some('.') {
            s.push('.');
            self.advance();
            while let Some(c) = self.peek() {
                if c.is_ascii_digit() {
                    s.push(c);
                    self.advance();
                } else {
                    break;
                }
            }
        }
        if matches!(self.peek(), Some('e') | Some('E')) {
            s.push(self.advance().unwrap());
            if matches!(self.peek(), Some('+') | Some('-')) {
                s.push(self.advance().unwrap());
            }
            while let Some(c) = self.peek() {
                if c.is_ascii_digit() {
                    s.push(c);
                    self.advance();
                } else {
                    break;
                }
            }
        }
        Json::Number(s.parse::<f64>().unwrap())
    }
}

fn escape_string(s: &str) -> String {
    let mut result = String::new();
    for c in s.chars() {
        match c {
            '"' => result.push_str("\\\""),
            '\\' => result.push_str("\\\\"),
            '\n' => result.push_str("\\n"),
            '\r' => result.push_str("\\r"),
            '\t' => result.push_str("\\t"),
            '\u{0008}' => result.push_str("\\b"),
            '\u{000C}' => result.push_str("\\f"),
            c if (c as u32) < 0x20 => {
                result.push_str(&format!("\\u{:04x}", c as u32));
            }
            c => result.push(c),
        }
    }
    result
}

fn serialize(value: &Json, indent: usize) -> String {
    let pad = "  ".repeat(indent);
    let inner = "  ".repeat(indent + 1);

    match value {
        Json::Null => "null".to_string(),
        Json::Bool(b) => b.to_string(),
        Json::Number(n) => format!("{}", n),
        Json::String(s) => format!("\"{}\"", escape_string(s)),
        Json::Array(arr) => {
            if arr.is_empty() {
                return "[]".to_string();
            }
            let items: Vec<String> = arr
                .iter()
                .map(|item| format!("{}{}", inner, serialize(item, indent + 1)))
                .collect();
            format!("[\n{}\n{}]", items.join(",\n"), pad)
        }
        Json::Object(map) => {
            if map.is_empty() {
                return "{}".to_string();
            }
            let items: Vec<String> = map
                .iter()
                .map(|(k, v)| {
                    format!(
                        "{}\"{}\": {}",
                        inner,
                        escape_string(k),
                        serialize(v, indent + 1)
                    )
                })
                .collect();
            format!("{{\n{}\n{}}}", items.join(",\n"), pad)
        }
    }
}

fn deep_merge(a: Json, b: Json) -> Json {
    match (a, b) {
        (Json::Object(mut obj_a), Json::Object(obj_b)) => {
            for (key, val_b) in obj_b {
                match obj_a.get_mut(&key) {
                    Some(existing) => {
                        let old = std::mem::replace(existing, Json::Null);
                        *existing = deep_merge(old, val_b);
                    }
                    None => {
                        obj_a.insert(key, val_b);
                    }
                }
            }
            Json::Object(obj_a)
        }
        (Json::Array(mut arr_a), Json::Array(arr_b)) => {
            for item in arr_b {
                if !arr_a.contains(&item) {
                    arr_a.push(item);
                }
            }
            Json::Array(arr_a)
        }
        (_, b) => b,
    }
}

fn main() {
    let path_a =
        "<tmp>";
    let path_b =
        "<tmp>";

    let content_a = fs::read_to_string(path_a).expect("Failed to read config_a.json");
    let content_b = fs::read_to_string(path_b).expect("Failed to read config_b.json");

    let json_a = Parser::new(&content_a).parse();
    let json_b = Parser::new(&content_b).parse();

    let merged = deep_merge(json_a, json_b);

    println!("{}", serialize(&merged, 0));
}
