    heap.push(Reverse((0.0, start_idx)));

    while let Some(Reverse((d, u))) = heap.pop() {
        if visited[u] {
            continue;
        }
        visited[u] = true;
        if d > dist[u] {
            continue;
        }
        for &(v, w) in &adj[u] {
            if !visited[v] && d + w < dist[v] {
                dist[v] = d + w;
                heap.push(Reverse((dist[v], v)));
            }
        }
    }

    println!("=== Shortest Paths from A ===");
