use std::collections::BTreeMap;
use std::fs;
use std::path::Path;

fn count_lines(content: &[u8]) -> u64 {
    if content.is_empty() {
        return 0;
    }
    let mut lines = content.iter().filter(|&&b| b == b'\n').count() as u64;
    if !content.last().map(|&b| b == b'\n').unwrap_or(false) {
        lines += 1;
    }
    lines
}

fn walk(dir: &Path, root: &Path, files: &mut Vec<(String, u64, u64)>) {
    let entries = match fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return,
    };

    for item in entries.flatten() {
        let path = item.path();

        let meta = match fs::symlink_metadata(&path) {
            Ok(m) => m,
            Err(_) => continue,
        };

        if meta.file_type().is_symlink() {
            continue;
        }

        if meta.is_dir() {
            walk(&path, root, files);
        } else if meta.is_file() {
            let rel = path.strip_prefix(root).unwrap_or(&path);
            let rel_str = rel.to_string_lossy().replace('\\', "/");

            let content = fs::read(&path).unwrap_or_default();
            let chars = content.len() as u64;
            let lines = count_lines(&content);

            files.push((rel_str, lines, chars));
        }
    }
}

fn main() {
    let root = Path::new("<tmp>");

    let mut files: Vec<(String, u64, u64)> = Vec::new();
    walk(root, root, &mut files);

    let mut groups: BTreeMap<String, Vec<(String, u64, u64)>> = BTreeMap::new();

    for (rel, lines, chars) in &files {
        let p = Path::new(rel);
        let ext = p.extension()
            .map(|e| format!(".{}", e.to_string_lossy()))
            .unwrap_or_else(|| String::new());
        groups.entry(ext).or_insert_with(Vec::new).push((rel.clone(), *lines, *chars));
    }

    for v in groups.values_mut() {
        v.sort_by(|a, b| a.0.cmp(&b.0));
    }

    print!("=== File Tree Analysis ===\n");
    print!("\n");

    let mut total_files: u64 = 0;
    let mut total_lines: u64 = 0;
    let mut total_chars: u64 = 0;

    for (ext, file_list) in &groups {
        let n_files = file_list.len() as u64;
        let n_lines: u64 = file_list.iter().map(|f| f.1).sum();
        let n_chars: u64 = file_list.iter().map(|f| f.2).sum();

        total_files += n_files;
        total_lines += n_lines;
        total_chars += n_chars;

        print!("Extension: {}\n", ext);
        print!("  Files: {}\n", n_files);
        print!("  Total Lines: {}\n", n_lines);
        print!("  Total Characters: {}\n", n_chars);
        for (rel, lines, chars) in file_list {
            print!("    {}: {} lines, {} chars\n", rel, lines, chars);
        }
    }

    print!("\n");
    print!("Total: {} files, {} lines, {} characters\n", total_files, total_lines, total_chars);
}

